/* Escape and unescape URL encoding in strings. The functions return a new

 * allocated string or NULL if an error occurred.  */



#include "setup.h"



#include <curl/curl.h>



#include "curl_memory.h"

#include "urldata.h"

#include "warnless.h"

#include "non-ascii.h"



